// Prototype TopUp (version du 28/08/2026) embarqué dans l application
export default "<!doctype html><html><head><meta charset=utf8><meta name=viewport content=\"width=device-width,initial-scale=1\"><style>:root{color-scheme:light}body{margin:0;padding:0;font:14px -apple-system,BlinkMacSystemFont,sans-serif;background:#faf9f5;color:#141413}img{max-width:100%}</style></head><body>\n<title>TopUp</title>\n<style>\n  @import url('https://fonts.googleapis.com/css2?family=Sora:wght@500;600;700;800&family=Manrope:wght@400;500;600;700&family=IBM+Plex+Mono:wght@500;600&display=swap');\n\n  :root {\n    --backdrop: #E7E4DC;\n    --bg: #F8F6F1;\n    --surface: #FFFFFF;\n    --surface-2: #F1EEE6;\n    --ink: #16181B;\n    --ink-soft: #5B5F5A;\n    --ink-faint: #93968E;\n    --line: #E4E0D5;\n\n    --brand: #FF5A36;\n    --brand-ink: #FFFFFF;\n\n    --cat-vetement: #D6537B;\n    --cat-vetement-soft: #FBE6EC;\n    --cat-cuisine: #D98A2B;\n    --cat-cuisine-soft: #FBEBD6;\n    --cat-outils: #3F8C5A;\n    --cat-outils-soft: #E1F0E4;\n    --cat-sponsor: #7C5CC4;\n    --cat-sponsor-soft: #EAE3F8;\n\n    --pay-faible: #8B93A7;\n    --pay-faible-soft: #ECEEF2;\n    --pay-moyen: #C99A2E;\n    --pay-moyen-soft: #F6ECD3;\n    --pay-eleve: #2E9E6D;\n    --pay-eleve-soft: #DFF2E7;\n    --bar-muted: #BEE3CE;\n\n    --shadow: rgba(22, 24, 27, 0.10);\n  }\n\n  @media (prefers-color-scheme: dark) {\n    :root:not([data-theme=\"light\"]) {\n      --backdrop: #0A0B0C;\n      --bg: #141518;\n      --surface: #1D1F23;\n      --surface-2: #24262B;\n      --ink: #F2F0EA;\n      --ink-soft: #ABAFA8;\n      --ink-faint: #6E726C;\n      --line: #303236;\n\n      --brand: #FF6E4E;\n      --brand-ink: #191008;\n\n      --cat-vetement: #E8749A;\n      --cat-vetement-soft: #3A2530;\n      --cat-cuisine: #E8A34B;\n      --cat-cuisine-soft: #3A2E1A;\n      --cat-outils: #5CB47E;\n      --cat-outils-soft: #1E3427;\n      --cat-sponsor: #A487E0;\n      --cat-sponsor-soft: #2C2440;\n\n      --pay-faible: #9AA0AE;\n      --pay-faible-soft: #24262B;\n      --pay-moyen: #E0B24C;\n      --pay-moyen-soft: #332A16;\n      --pay-eleve: #4FBF8B;\n      --pay-eleve-soft: #16302422;\n      --bar-muted: #2E4A3E;\n\n      --shadow: rgba(0, 0, 0, 0.45);\n    }\n  }\n\n  :root[data-theme=\"dark\"] {\n    --backdrop: #0A0B0C;\n    --bg: #141518;\n    --surface: #1D1F23;\n    --surface-2: #24262B;\n    --ink: #F2F0EA;\n    --ink-soft: #ABAFA8;\n    --ink-faint: #6E726C;\n    --line: #303236;\n\n    --brand: #FF6E4E;\n    --brand-ink: #191008;\n\n    --cat-vetement: #E8749A;\n    --cat-vetement-soft: #3A2530;\n    --cat-cuisine: #E8A34B;\n    --cat-cuisine-soft: #3A2E1A;\n    --cat-outils: #5CB47E;\n    --cat-outils-soft: #1E3427;\n    --cat-sponsor: #A487E0;\n    --cat-sponsor-soft: #2C2440;\n\n    --pay-faible: #9AA0AE;\n    --pay-faible-soft: #24262B;\n    --pay-moyen: #E0B24C;\n    --pay-moyen-soft: #332A16;\n    --pay-eleve: #4FBF8B;\n    --pay-eleve-soft: #16302422;\n\n    --shadow: rgba(0, 0, 0, 0.45);\n  }\n\n  * { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }\n\n  html, body {\n    height: 100%;\n    margin: 0;\n  }\n\n  body {\n    background: var(--backdrop);\n    color: var(--ink);\n    font-family: 'Manrope', system-ui, sans-serif;\n    display: flex;\n    justify-content: center;\n    min-height: 100dvh;\n  }\n\n  .phone {\n    width: 100%;\n    max-width: 430px;\n    min-height: 100dvh;\n    background: var(--bg);\n    display: flex;\n    flex-direction: column;\n    position: relative;\n    box-shadow: 0 30px 60px var(--shadow);\n  }\n\n  @media (min-width: 431px) {\n    .phone { margin: 1.75rem 0; min-height: calc(100dvh - 3.5rem); border-radius: 34px; overflow: hidden; }\n  }\n\n  /* ---------- Header ---------- */\n  .app-header {\n    padding: 1.35rem 1.25rem 0.9rem;\n    background: var(--bg);\n    position: sticky;\n    top: 0;\n    z-index: 5;\n  }\n\n  .brand-row {\n    display: flex;\n    align-items: center;\n    gap: 0.55rem;\n  }\n\n  .tracker-pill {\n    margin-left: auto;\n    font-family: 'IBM Plex Mono', monospace;\n    font-size: 0.72rem;\n    font-weight: 700;\n    color: var(--pay-eleve);\n    background: var(--pay-eleve-soft);\n    border: none;\n    border-radius: 999px;\n    padding: 0.4rem 0.7rem;\n    cursor: pointer;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.3rem;\n    font-variant-numeric: tabular-nums;\n  }\n\n  /* ---------- Suivi mensuel (drawer) ---------- */\n  .drawer-overlay {\n    position: fixed;\n    inset: 0;\n    background: rgba(0, 0, 0, 0.45);\n    display: flex;\n    align-items: flex-end;\n    justify-content: center;\n    opacity: 0;\n    pointer-events: none;\n    transition: opacity 0.2s ease;\n    z-index: 20;\n  }\n\n  .drawer-overlay.open { opacity: 1; pointer-events: auto; }\n\n  .drawer {\n    width: 100%;\n    max-width: 430px;\n    max-height: 82%;\n    background: var(--bg);\n    border-radius: 22px 22px 0 0;\n    padding: 0.9rem 1.25rem calc(1.25rem + env(safe-area-inset-bottom, 0px));\n    overflow-y: auto;\n    transform: translateY(100%);\n    transition: transform 0.25s ease;\n  }\n\n  .drawer-overlay.open .drawer { transform: translateY(0); }\n\n  .drawer-handle {\n    width: 36px;\n    height: 4px;\n    background: var(--line);\n    border-radius: 2px;\n    margin: 0 auto 0.9rem;\n  }\n\n  .drawer-head {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    margin-bottom: 0.4rem;\n  }\n\n  .drawer-head h3 {\n    font-family: 'Sora', sans-serif;\n    font-size: 1.05rem;\n    margin: 0;\n  }\n\n  .drawer-close {\n    border: none;\n    background: var(--surface-2);\n    width: 28px;\n    height: 28px;\n    border-radius: 50%;\n    color: var(--ink-soft);\n    cursor: pointer;\n  }\n\n  .drawer-note {\n    font-size: 0.76rem;\n    color: var(--ink-soft);\n    line-height: 1.5;\n    margin: 0 0 1rem;\n  }\n\n  .drawer-total {\n    display: flex;\n    justify-content: space-between;\n    align-items: baseline;\n    background: var(--pay-eleve-soft);\n    border-radius: 12px;\n    padding: 0.8rem 1rem;\n    margin-bottom: 1rem;\n  }\n\n  .drawer-total-label { font-size: 0.75rem; color: var(--ink-soft); }\n\n  .drawer-total-amount {\n    font-family: 'IBM Plex Mono', monospace;\n    font-weight: 700;\n    font-size: 1.3rem;\n    color: var(--pay-eleve);\n    font-variant-numeric: tabular-nums;\n  }\n\n  .chart-wrap { margin-bottom: 1.1rem; }\n\n  .chart-title {\n    font-family: 'Sora', sans-serif;\n    font-weight: 700;\n    font-size: 0.82rem;\n    margin: 0 0 0.55rem;\n  }\n\n  .chart-empty {\n    font-size: 0.76rem;\n    color: var(--ink-faint);\n    text-align: center;\n    padding: 1.3rem 0.8rem;\n    border: 1px dashed var(--line);\n    border-radius: 12px;\n    line-height: 1.5;\n  }\n\n  .chart-svg-wrap { position: relative; }\n\n  .chart-tooltip {\n    position: absolute;\n    pointer-events: none;\n    background: var(--ink);\n    color: var(--bg);\n    font-family: 'IBM Plex Mono', monospace;\n    font-size: 0.68rem;\n    padding: 0.35rem 0.6rem;\n    border-radius: 7px;\n    transform: translate(-50%, -120%);\n    white-space: nowrap;\n    opacity: 0;\n    transition: opacity 0.12s ease;\n    z-index: 2;\n    top: 0;\n    left: 0;\n  }\n\n  .chart-tooltip.show { opacity: 1; }\n  .chart-tooltip .val { font-weight: 700; }\n\n  .stat-row {\n    display: flex;\n    gap: 0.6rem;\n    margin: 0.7rem 0 1.1rem;\n  }\n\n  .stat-tile {\n    flex: 1;\n    background: var(--surface-2);\n    border-radius: 12px;\n    padding: 0.6rem 0.75rem;\n  }\n\n  .stat-tile .stat-value {\n    font-family: 'Sora', sans-serif;\n    font-weight: 700;\n    font-size: 1.15rem;\n    display: block;\n  }\n\n  .stat-tile .stat-label {\n    font-size: 0.68rem;\n    color: var(--ink-faint);\n  }\n\n  .history-delta {\n    font-size: 0.78rem;\n    color: var(--ink-soft);\n    margin: 0.55rem 0 0;\n  }\n\n  .history-delta strong { font-variant-numeric: tabular-nums; }\n\n  .drawer-form {\n    display: grid;\n    grid-template-columns: 1fr;\n    gap: 0.55rem;\n    margin-bottom: 1.1rem;\n  }\n\n  .drawer-form select,\n  .drawer-form input {\n    font-family: 'Manrope', sans-serif;\n    font-size: 0.85rem;\n    padding: 0.6rem 0.75rem;\n    border-radius: 10px;\n    border: 1px solid var(--line);\n    background: var(--surface);\n    color: var(--ink);\n  }\n\n  .drawer-form button {\n    font-family: 'Sora', sans-serif;\n    font-weight: 700;\n    font-size: 0.85rem;\n    background: var(--brand);\n    color: var(--brand-ink);\n    border: none;\n    border-radius: 10px;\n    padding: 0.65rem;\n    cursor: pointer;\n  }\n\n  .drawer-list { display: flex; flex-direction: column; gap: 0.45rem; }\n\n  .drawer-empty { font-size: 0.78rem; color: var(--ink-faint); text-align: center; padding: 1rem 0; }\n\n  .entry-row {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: 10px;\n    padding: 0.55rem 0.8rem;\n    font-size: 0.8rem;\n  }\n\n  .entry-row .src { font-weight: 600; }\n  .entry-row .date-note { font-size: 0.68rem; color: var(--ink-faint); display: block; }\n  .entry-row .amt { font-family: 'IBM Plex Mono', monospace; font-weight: 700; color: var(--pay-eleve); }\n  .entry-row .del {\n    border: none; background: none; color: var(--ink-faint); cursor: pointer; font-size: 0.9rem; margin-left: 0.5rem;\n  }\n\n  .brand-mark {\n    width: 34px;\n    height: 34px;\n    flex-shrink: 0;\n    display: block;\n  }\n\n  .brand-name {\n    font-family: 'Sora', sans-serif;\n    font-weight: 700;\n    font-size: 1.2rem;\n    letter-spacing: -0.01em;\n  }\n\n  .tagline {\n    margin: 0.5rem 0 0;\n    font-size: 0.82rem;\n    color: var(--ink-soft);\n    max-width: 32ch;\n  }\n\n  .disclaimer {\n    margin: 0.4rem 0 0;\n    font-size: 0.7rem;\n    color: var(--ink-faint);\n  }\n\n  .settings-btn {\n    margin-left: auto;\n    width: 30px;\n    height: 30px;\n    border-radius: 50%;\n    border: 1px solid var(--line);\n    background: var(--surface);\n    color: var(--ink-soft);\n    font-size: 0.85rem;\n    cursor: pointer;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  .guarantee-banner {\n    display: flex;\n    align-items: center;\n    gap: 0.5rem;\n    background: var(--cat-sponsor-soft);\n    color: var(--cat-sponsor);\n    border-radius: 11px;\n    padding: 0.55rem 0.75rem;\n    font-size: 0.75rem;\n    font-weight: 600;\n    margin-top: 0.85rem;\n  }\n\n  .guarantee-banner.positive { background: var(--pay-eleve-soft); color: var(--pay-eleve); }\n\n  /* ---------- Loyalty tier ---------- */\n  .tier-box {\n    margin: 0.85rem 1.25rem 0.2rem;\n    background: var(--surface-2);\n    border-radius: 12px;\n    padding: 0.7rem 0.9rem;\n  }\n\n  .tier-head {\n    display: flex;\n    justify-content: space-between;\n    align-items: baseline;\n    font-size: 0.76rem;\n    margin-bottom: 0.4rem;\n  }\n\n  .tier-name { font-family: 'Sora', sans-serif; font-weight: 700; color: var(--ink); }\n  .tier-count { color: var(--ink-faint); font-family: 'IBM Plex Mono', monospace; }\n\n  .tier-track {\n    height: 6px;\n    border-radius: 3px;\n    background: var(--line);\n    overflow: hidden;\n  }\n\n  .tier-fill {\n    height: 100%;\n    background: var(--cat-sponsor);\n    border-radius: 3px;\n    transition: width 0.3s ease;\n  }\n\n  .tier-celebrate {\n    margin-top: 0.5rem;\n    font-size: 0.74rem;\n    color: var(--cat-sponsor);\n    font-weight: 600;\n  }\n\n  .skip-btn {\n    margin-top: 0.6rem;\n    width: 100%;\n    font-family: 'Sora', sans-serif;\n    font-weight: 700;\n    font-size: 0.78rem;\n    color: var(--cat-sponsor);\n    background: var(--cat-sponsor-soft);\n    border: 1px solid var(--cat-sponsor);\n    border-radius: 9px;\n    padding: 0.5rem;\n    cursor: pointer;\n  }\n\n  .premium-price {\n    font-family: 'Sora', sans-serif;\n    font-weight: 800;\n    font-size: 1.6rem;\n    text-align: center;\n    margin: 0.4rem 0 0.8rem;\n  }\n\n  .premium-includes {\n    margin: 0 0 1rem;\n    padding-left: 1.1rem;\n    font-size: 0.82rem;\n    color: var(--ink-soft);\n  }\n\n  .premium-includes li { margin-bottom: 0.35rem; }\n\n  .demo-flag {\n    font-size: 0.7rem;\n    color: var(--ink-faint);\n    text-align: center;\n    margin-top: 0.7rem;\n  }\n\n  /* ---------- Global (Premium Plus) ---------- */\n  .paywall-card {\n    background: var(--surface);\n    border: 1px dashed var(--line);\n    border-radius: 16px;\n    padding: 1.3rem 1.1rem;\n    text-align: center;\n  }\n\n  .paywall-card h3 {\n    font-family: 'Sora', sans-serif;\n    font-size: 1rem;\n    margin: 0 0 0.5rem;\n  }\n\n  .paywall-card p {\n    font-size: 0.82rem;\n    color: var(--ink-soft);\n    line-height: 1.5;\n    margin: 0 0 0.9rem;\n  }\n\n  .paywall-preview {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 0.4rem;\n    justify-content: center;\n    margin-bottom: 1rem;\n    filter: blur(0.3px);\n    opacity: 0.6;\n  }\n\n  .paywall-preview span {\n    font-family: 'IBM Plex Mono', monospace;\n    font-size: 0.68rem;\n    background: var(--surface-2);\n    border-radius: 999px;\n    padding: 0.3rem 0.65rem;\n    color: var(--ink-faint);\n  }\n\n  .paywall-btn {\n    font-family: 'Sora', sans-serif;\n    font-weight: 700;\n    font-size: 0.85rem;\n    color: var(--brand-ink);\n    background: var(--brand);\n    border: none;\n    border-radius: 10px;\n    padding: 0.65rem 1.3rem;\n    cursor: pointer;\n  }\n\n  .paywall-honest {\n    font-size: 0.7rem;\n    color: var(--ink-faint);\n    margin-top: 0.8rem;\n    line-height: 1.5;\n  }\n\n  .premium-flag {\n    display: inline-flex;\n    align-items: center;\n    gap: 0.2rem;\n    font-size: 0.65rem;\n    font-weight: 700;\n    color: var(--cat-sponsor);\n    background: var(--cat-sponsor-soft);\n    padding: 0.15rem 0.4rem;\n    border-radius: 6px;\n    margin-left: 0.35rem;\n  }\n\n  /* ---------- Preferences overlay ---------- */\n  .pref-option {\n    display: flex;\n    align-items: center;\n    gap: 0.65rem;\n    padding: 0.7rem 0.2rem;\n    border-bottom: 1px solid var(--line);\n    font-size: 0.86rem;\n  }\n\n  .pref-option:last-child { border-bottom: none; }\n  .pref-option input { width: 18px; height: 18px; accent-color: var(--brand); }\n  .pref-option label { flex: 1; }\n  .pref-hint { font-size: 0.72rem; color: var(--ink-faint); }\n\n  /* ---------- Segmented tabs (top, section identity) ---------- */\n  .segmented {\n    display: flex;\n    gap: 0.4rem;\n    margin-top: 1.1rem;\n    background: var(--surface-2);\n    border-radius: 14px;\n    padding: 0.3rem;\n  }\n\n  .segmented button {\n    flex: 1;\n    border: none;\n    background: transparent;\n    font-family: 'Sora', sans-serif;\n    font-weight: 600;\n    font-size: 0.88rem;\n    color: var(--ink-soft);\n    padding: 0.55rem 0;\n    border-radius: 11px;\n    cursor: pointer;\n    transition: background 0.18s ease, color 0.18s ease, box-shadow 0.18s ease;\n  }\n\n  .segmented button.active {\n    background: var(--surface);\n    color: var(--ink);\n    box-shadow: 0 2px 6px var(--shadow);\n  }\n\n  .segmented button .dot {\n    display: inline-block;\n    width: 7px;\n    height: 7px;\n    border-radius: 50%;\n    margin-right: 0.4rem;\n    vertical-align: middle;\n  }\n\n  #tabSondages .dot { background: var(--pay-eleve); }\n  #tabEssais .dot { background: var(--cat-sponsor); }\n\n  /* ---------- Legend ---------- */\n  .legend {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 0.5rem 0.9rem;\n    padding: 0.85rem 1.25rem 0.2rem;\n    font-size: 0.72rem;\n    color: var(--ink-faint);\n  }\n\n  .legend span { display: inline-flex; align-items: center; gap: 0.32rem; }\n  .legend i { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }\n\n  /* ---------- Filter chips ---------- */\n  .chips {\n    display: flex;\n    gap: 0.5rem;\n    padding: 0.75rem 1.25rem 0.25rem;\n    overflow-x: auto;\n    scrollbar-width: none;\n  }\n\n  .chips::-webkit-scrollbar { display: none; }\n\n  .chip {\n    flex-shrink: 0;\n    font-family: 'Manrope', sans-serif;\n    font-weight: 600;\n    font-size: 0.78rem;\n    padding: 0.42rem 0.85rem;\n    border-radius: 999px;\n    border: 1px solid var(--line);\n    background: var(--surface);\n    color: var(--ink-soft);\n    cursor: pointer;\n    white-space: nowrap;\n    transition: all 0.15s ease;\n  }\n\n  .chip.active {\n    background: var(--ink);\n    border-color: var(--ink);\n    color: var(--bg);\n  }\n\n  /* ---------- List ---------- */\n  .list {\n    flex: 1;\n    padding: 0.9rem 1.05rem 6.5rem;\n    display: flex;\n    flex-direction: column;\n    gap: 0.7rem;\n    overflow-y: auto;\n  }\n\n  .empty-state {\n    text-align: center;\n    padding: 2.5rem 1.5rem;\n    color: var(--ink-faint);\n    font-size: 0.85rem;\n    line-height: 1.6;\n  }\n\n  .card {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: 16px;\n    padding: 0.95rem 1rem;\n    display: grid;\n    grid-template-columns: 4px 1fr;\n    gap: 0.85rem;\n    position: relative;\n    box-shadow: 0 1px 3px var(--shadow);\n  }\n\n  .card-bar { border-radius: 4px; }\n\n  .card-main { min-width: 0; }\n\n  .card-top {\n    display: flex;\n    justify-content: space-between;\n    align-items: flex-start;\n    gap: 0.5rem;\n  }\n\n  .card-title {\n    font-family: 'Sora', sans-serif;\n    font-weight: 700;\n    font-size: 0.95rem;\n    margin: 0;\n  }\n\n  .check-btn {\n    flex-shrink: 0;\n    width: 26px;\n    height: 26px;\n    border-radius: 50%;\n    border: 1.5px solid var(--line);\n    background: var(--surface);\n    color: var(--ink-faint);\n    font-size: 0.8rem;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    cursor: pointer;\n    transition: all 0.15s ease;\n  }\n\n  .check-btn.done {\n    background: var(--pay-eleve);\n    border-color: var(--pay-eleve);\n    color: #fff;\n  }\n\n  .card-desc {\n    margin: 0.25rem 0 0.6rem;\n    font-size: 0.82rem;\n    color: var(--ink-soft);\n    line-height: 1.45;\n  }\n\n  .badge-row {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 0.4rem;\n    margin-bottom: 0.7rem;\n  }\n\n  .badge {\n    font-family: 'IBM Plex Mono', monospace;\n    font-size: 0.68rem;\n    font-weight: 600;\n    padding: 0.28rem 0.55rem;\n    border-radius: 7px;\n    display: inline-flex;\n    align-items: center;\n    gap: 0.3rem;\n  }\n\n  .card-foot {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    gap: 0.6rem;\n  }\n\n  .select-note {\n    font-size: 0.7rem;\n    color: var(--ink-faint);\n    line-height: 1.3;\n  }\n\n  .open-btn {\n    flex-shrink: 0;\n    font-family: 'Sora', sans-serif;\n    font-weight: 600;\n    font-size: 0.78rem;\n    text-decoration: none;\n    color: var(--brand-ink);\n    background: var(--brand);\n    padding: 0.45rem 0.9rem;\n    border-radius: 10px;\n    transition: transform 0.12s ease, opacity 0.12s ease;\n  }\n\n  .open-btn:active { transform: scale(0.96); }\n\n  /* ---------- Bottom tab bar ---------- */\n  .tabbar {\n    position: sticky;\n    bottom: 0;\n    display: flex;\n    background: var(--surface);\n    border-top: 1px solid var(--line);\n    padding: 0.55rem 1rem calc(0.55rem + env(safe-area-inset-bottom, 0px));\n  }\n\n  .tab-btn {\n    flex: 1;\n    background: none;\n    border: none;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 0.2rem;\n    padding: 0.35rem 0;\n    cursor: pointer;\n    color: var(--ink-faint);\n  }\n\n  .tab-btn .icon {\n    width: 22px;\n    height: 22px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 1.05rem;\n  }\n\n  .tab-btn .label {\n    font-family: 'Sora', sans-serif;\n    font-size: 0.68rem;\n    font-weight: 600;\n  }\n\n  .tab-btn.active { color: var(--brand); }\n\n  /* ---------- Offres du jour ---------- */\n  .info-box {\n    margin: 0 1.25rem 0.85rem;\n    padding: 0.8rem 0.9rem;\n    background: var(--surface-2);\n    border: 1px solid var(--line);\n    border-radius: 12px;\n    font-size: 0.73rem;\n    color: var(--ink-soft);\n    line-height: 1.55;\n  }\n\n  .info-box strong { color: var(--ink); }\n\n  .shuffle-row {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    padding: 0 1.25rem 0.9rem;\n  }\n\n  .shuffle-row .count {\n    font-size: 0.72rem;\n    color: var(--ink-faint);\n  }\n\n  .shuffle-btn {\n    font-family: 'Sora', sans-serif;\n    font-weight: 600;\n    font-size: 0.78rem;\n    color: var(--ink);\n    background: var(--surface);\n    border: 1px solid var(--line);\n    padding: 0.42rem 0.85rem;\n    border-radius: 999px;\n    cursor: pointer;\n  }\n\n  .shuffle-btn:active { transform: scale(0.97); }\n\n  .combo-card {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: 16px;\n    padding: 1rem 1.05rem;\n    box-shadow: 0 1px 3px var(--shadow);\n  }\n\n  .combo-title {\n    font-family: 'Sora', sans-serif;\n    font-weight: 700;\n    font-size: 0.92rem;\n    margin: 0 0 0.7rem;\n    display: flex;\n    align-items: center;\n    gap: 0.4rem;\n  }\n\n  .combo-item-row {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n    gap: 0.6rem;\n    padding: 0.5rem 0;\n    border-bottom: 1px dashed var(--line);\n  }\n\n  .combo-item-row:last-of-type { border-bottom: none; }\n\n  .combo-item-info { min-width: 0; }\n\n  .combo-item-name {\n    font-weight: 700;\n    font-size: 0.83rem;\n    display: block;\n  }\n\n  .combo-item-meta {\n    font-size: 0.7rem;\n    color: var(--ink-faint);\n  }\n\n  .combo-item-link {\n    flex-shrink: 0;\n    font-family: 'IBM Plex Mono', monospace;\n    font-size: 0.68rem;\n    font-weight: 600;\n    color: var(--brand);\n    text-decoration: none;\n    border: 1px solid var(--brand);\n    border-radius: 7px;\n    padding: 0.25rem 0.5rem;\n  }\n\n  .total-line {\n    margin-top: 0.75rem;\n    padding-top: 0.75rem;\n    border-top: 1px solid var(--line);\n    display: flex;\n    justify-content: space-between;\n    align-items: baseline;\n  }\n\n  .total-label { font-size: 0.72rem; color: var(--ink-faint); }\n\n  .total-amount {\n    font-family: 'IBM Plex Mono', monospace;\n    font-weight: 700;\n    font-size: 1.15rem;\n    color: var(--pay-eleve);\n    font-variant-numeric: tabular-nums;\n  }\n\n  .product-line {\n    margin-top: 0.55rem;\n    font-size: 0.73rem;\n    color: var(--ink-soft);\n    background: var(--cat-sponsor-soft);\n    color: var(--cat-sponsor);\n    padding: 0.4rem 0.6rem;\n    border-radius: 8px;\n  }\n\n  .offres-divider {\n    display: flex;\n    align-items: center;\n    gap: 0.6rem;\n    margin: 0.4rem 0 0.2rem;\n    color: var(--ink-faint);\n    font-family: 'Sora', sans-serif;\n    font-weight: 700;\n    font-size: 0.82rem;\n  }\n\n  .offres-divider::before,\n  .offres-divider::after {\n    content: '';\n    flex: 1;\n    height: 1px;\n    background: var(--line);\n  }\n\n  .cashback-note {\n    font-size: 0.76rem;\n    color: var(--ink-soft);\n    margin: -0.1rem 0 0.2rem;\n    line-height: 1.5;\n  }\n\n  .cashback-card {\n    background: var(--surface);\n    border: 1px solid var(--line);\n    border-radius: 14px;\n    padding: 0.8rem 0.95rem;\n    display: flex;\n    align-items: center;\n    gap: 0.75rem;\n  }\n\n  .cashback-icon {\n    width: 38px;\n    height: 38px;\n    border-radius: 10px;\n    background: var(--pay-eleve-soft);\n    color: var(--pay-eleve);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 1.1rem;\n    flex-shrink: 0;\n  }\n\n  .cashback-body { flex: 1; min-width: 0; }\n  .cashback-name { font-family: 'Sora', sans-serif; font-weight: 700; font-size: 0.88rem; }\n  .cashback-desc { font-size: 0.76rem; color: var(--ink-soft); margin: 0.1rem 0 0.25rem; }\n  .cashback-avail { font-size: 0.68rem; color: var(--ink-faint); font-family: 'IBM Plex Mono', monospace; }\n\n  @media (prefers-reduced-motion: reduce) {\n    * { transition: none !important; }\n  }\n</style>\n\n<div class=\"phone\">\n\n  <div class=\"app-header\">\n    <div class=\"brand-row\">\n      <svg class=\"brand-mark\" viewBox=\"0 0 100 100\" xmlns=\"http://www.w3.org/2000/svg\">\n        <rect x=\"0\" y=\"0\" width=\"100\" height=\"100\" rx=\"22\" fill=\"var(--brand)\"/>\n        <path d=\"M24,76 L24,64 Q24,60 28,60 L28,60 Q32,60 32,64 L32,76 Z\" fill=\"#FFFFFF\"/>\n        <path d=\"M41,76 L41,52 Q41,48 45,48 L45,48 Q49,48 49,52 L49,76 Z\" fill=\"#FFFFFF\"/>\n        <path d=\"M58,76 L58,38 Q58,34 62,34 L62,34 Q66,34 66,38 L66,76 Z\" fill=\"#FFFFFF\"/>\n        <path d=\"M75,76 L75,24 Q75,20 79,20 L79,20 Q83,20 83,24 L83,76 Z\" fill=\"#FFFFFF\"/>\n        <circle cx=\"79\" cy=\"20\" r=\"13\" fill=\"#FFFFFF\" stroke=\"var(--brand)\" stroke-width=\"3\"/>\n        <text x=\"79\" y=\"25\" text-anchor=\"middle\" font-family=\"Arial, sans-serif\" font-weight=\"700\" font-size=\"15\" fill=\"var(--brand)\">&#8364;</text>\n      </svg>\n      <div class=\"brand-name\">Top<span style=\"color:var(--brand)\">Up</span></div>\n      <button class=\"tracker-pill\" id=\"trackerPillBtn\">💶 <span id=\"trackerPillAmount\">0,00 €</span></button>\n      <button class=\"settings-btn\" id=\"settingsBtn\" title=\"Mes préférences\">⚙️</button>\n    </div>\n    <p class=\"tagline\">Sondages et essais produits triés par temps et par gain — un tap pour ouvrir la source officielle.</p>\n    <p class=\"disclaimer\">Estimations indicatives · le paiement se fait toujours via la plateforme d'origine, jamais dans l'app.</p>\n    <div class=\"guarantee-banner\" id=\"guaranteeBanner\"></div>\n\n    <div class=\"segmented\">\n      <button id=\"tabSondages\" class=\"active\"><span class=\"dot\"></span>Sondage</button>\n      <button id=\"tabEssais\"><span class=\"dot\"></span>Essai</button>\n      <button id=\"tabOffres\"><span class=\"dot\" style=\"background:var(--brand)\"></span>Offres</button>\n      <button id=\"tabIntl\"><span class=\"dot\" style=\"background:var(--cat-sponsor)\"></span>🌍</button>\n    </div>\n  </div>\n\n  <div class=\"tier-box\" id=\"tierBox\"></div>\n\n  <div id=\"legendSondages\" class=\"legend\">\n    <span><i style=\"background:var(--pay-faible)\"></i>Gain faible</span>\n    <span><i style=\"background:var(--pay-moyen)\"></i>Gain moyen</span>\n    <span><i style=\"background:var(--pay-eleve)\"></i>Gain élevé</span>\n    <span>⚡ Rapide · 🕰 Long</span>\n  </div>\n\n  <div id=\"legendEssais\" class=\"legend\" style=\"display:none\">\n    <span><i style=\"background:var(--cat-vetement)\"></i>Vêtement</span>\n    <span><i style=\"background:var(--cat-cuisine)\"></i>Cuisine &amp; alim.</span>\n    <span><i style=\"background:var(--cat-outils)\"></i>Outils &amp; jardin</span>\n    <span><i style=\"background:var(--cat-sponsor)\"></i>Sponsoring</span>\n  </div>\n\n  <div id=\"chipsSondages\" class=\"chips\">\n    <button class=\"chip active\" data-filter=\"tous\">Tous</button>\n    <button class=\"chip\" data-filter=\"rapide\">⚡ Rapide</button>\n    <button class=\"chip\" data-filter=\"eleve\">💰 Bien payé</button>\n    <button class=\"chip\" data-filter=\"rapide-eleve\">🏆 Rapide &amp; payé</button>\n  </div>\n\n  <div id=\"chipsEssais\" class=\"chips\" style=\"display:none\">\n    <button class=\"chip active\" data-filter=\"tous\">Tous</button>\n    <button class=\"chip\" data-filter=\"vetement\">Vêtement</button>\n    <button class=\"chip\" data-filter=\"cuisine\">Cuisine</button>\n    <button class=\"chip\" data-filter=\"outils\">Outils &amp; jardin</button>\n    <button class=\"chip\" data-filter=\"sponsoring\">Sponsoring</button>\n  </div>\n\n  <div id=\"infoOffres\" class=\"info-box\" style=\"display:none\">\n    <strong>Comment lire ces cumuls :</strong> chaque montant additionne les fourchettes réellement publiées par les plateformes elles-mêmes — ce n'est pas un gain garanti, ni un chiffre trouvé en direct sur ton compte (aucune appli tierce n'a accès aux sondages précis qui te seront proposés). Les gros totaux à 3 chiffres annoncés par certains sites \"opportunités\" ne sont pas soutenus par les vrais chiffres du secteur — on reste sur des cumuls réalistes.\n  </div>\n\n  <div id=\"shuffleRowOffres\" class=\"shuffle-row\" style=\"display:none\">\n    <span class=\"count\" id=\"offresCount\"></span>\n    <button class=\"shuffle-btn\" id=\"shuffleBtn\">🔄 Nouvelle sélection</button>\n  </div>\n\n  <div id=\"listSondages\" class=\"list\"></div>\n  <div id=\"listEssais\" class=\"list\" style=\"display:none\"></div>\n  <div id=\"listOffres\" class=\"list\" style=\"display:none\"></div>\n  <div id=\"listIntl\" class=\"list\" style=\"display:none\"></div>\n\n  <nav class=\"tabbar\">\n    <button class=\"tab-btn active\" data-tab=\"sondages\">\n      <span class=\"icon\">📝</span>\n      <span class=\"label\">Sondage</span>\n    </button>\n    <button class=\"tab-btn\" data-tab=\"essais\">\n      <span class=\"icon\">📦</span>\n      <span class=\"label\">Essai</span>\n    </button>\n    <button class=\"tab-btn\" data-tab=\"offres\">\n      <span class=\"icon\">✨</span>\n      <span class=\"label\">Offres</span>\n    </button>\n    <button class=\"tab-btn\" data-tab=\"intl\">\n      <span class=\"icon\">🌍</span>\n      <span class=\"label\">Monde</span>\n    </button>\n  </nav>\n\n</div>\n\n<div class=\"drawer-overlay\" id=\"drawerOverlay\">\n  <div class=\"drawer\" id=\"drawer\">\n    <div class=\"drawer-handle\"></div>\n    <div class=\"drawer-head\">\n      <h3>Suivi de tes gains</h3>\n      <button class=\"drawer-close\" id=\"drawerClose\">✕</button>\n    </div>\n    <p class=\"drawer-note\">Ajoute un montant une fois qu'il est vraiment sur ton compte ou ta carte cadeau — ce total, c'est ce que tu as réellement encaissé ce mois-ci, pas une estimation ni une promesse.</p>\n    <div class=\"drawer-total\">\n      <span class=\"drawer-total-label\">Total encaissé ce mois-ci</span>\n      <span class=\"drawer-total-amount\" id=\"drawerTotalAmount\">0,00 €</span>\n    </div>\n\n    <div class=\"chart-wrap\">\n      <h4 class=\"chart-title\">Ta progression, activité après activité</h4>\n      <div id=\"chartContainer\"></div>\n    </div>\n\n    <div class=\"stat-row\">\n      <div class=\"stat-tile\">\n        <span class=\"stat-value\" id=\"statSurveys\">0</span>\n        <span class=\"stat-label\">sondages / tests répondus</span>\n      </div>\n      <div class=\"stat-tile\">\n        <span class=\"stat-value\" id=\"statTrials\">0</span>\n        <span class=\"stat-label\">produits essayés</span>\n      </div>\n    </div>\n\n    <div class=\"chart-wrap\">\n      <h4 class=\"chart-title\">Historique des 6 derniers mois</h4>\n      <div id=\"historyContainer\"></div>\n      <p class=\"history-delta\" id=\"historyDelta\"></p>\n    </div>\n\n    <form class=\"drawer-form\" id=\"drawerForm\">\n      <select id=\"entrySource\" required></select>\n      <input type=\"number\" id=\"entryAmount\" step=\"0.01\" min=\"0\" placeholder=\"Montant reçu en €\" required />\n      <input type=\"date\" id=\"entryDate\" />\n      <button type=\"submit\">Ajouter au suivi</button>\n    </form>\n    <div class=\"drawer-list\" id=\"drawerList\"></div>\n  </div>\n</div>\n\n<div class=\"drawer-overlay\" id=\"premiumOverlay\">\n  <div class=\"drawer\" id=\"premiumDrawer\">\n    <div class=\"drawer-handle\"></div>\n    <div class=\"drawer-head\">\n      <h3>Passer direct au Premium</h3>\n      <button class=\"drawer-close\" id=\"premiumClose\">✕</button>\n    </div>\n    <p class=\"drawer-note\">Ça ne débloque pas un accès qui serait autrement fermé : Testapic, UserTesting et les autres restent gratuits et ouverts à tout le monde, avec ou sans TopUp. Ce que ça change, c'est uniquement dans l'app :</p>\n    <div class=\"premium-price\">1,00 €</div>\n    <ul class=\"premium-includes\">\n      <li>Le badge ⭐ Premium et la mise en avant des offres les mieux payées, tout de suite au lieu d'après 15 réponses</li>\n      <li>L'interface personnalisée selon tes préférences, activée immédiatement</li>\n    </ul>\n    <button class=\"open-btn\" id=\"confirmPremiumBtn\" style=\"width:100%;text-align:center;padding:0.7rem;font-size:0.85rem\">Confirmer (démo)</button>\n    <p class=\"demo-flag\">Démo : aucun paiement réel n'est prélevé ici. Une vraie mise en production nécessiterait un moyen de paiement branché (Stripe, App Store, Play Store).</p>\n  </div>\n</div>\n\n<div class=\"drawer-overlay\" id=\"premiumPlusOverlay\">\n  <div class=\"drawer\" id=\"premiumPlusDrawer\">\n    <div class=\"drawer-handle\"></div>\n    <div class=\"drawer-head\">\n      <h3>Débloquer l'onglet International</h3>\n      <button class=\"drawer-close\" id=\"premiumPlusClose\">✕</button>\n    </div>\n    <p class=\"drawer-note\">Ces plateformes restent gratuites et ouvertes à tout le monde directement sur leur site. Ce que tu payes, c'est le tri : une sélection vérifiée, centralisée, avec des liens directs, tenue à jour. Les sondages proposés restent en anglais.</p>\n    <div class=\"premium-price\">2,99 €</div>\n    <ul class=\"premium-includes\">\n      <li>L'onglet 🌍 International : Prolific, Survey Junkie, Branded Surveys, Pinecone Research, YouGov</li>\n      <li>Déblocage unique, pas d'abonnement</li>\n    </ul>\n    <button class=\"open-btn\" id=\"confirmPremiumPlusBtn\" style=\"width:100%;text-align:center;padding:0.7rem;font-size:0.85rem\">Confirmer (démo)</button>\n    <p class=\"demo-flag\">Démo : aucun paiement réel n'est prélevé ici. Une vraie mise en production nécessiterait un moyen de paiement branché (Stripe, App Store, Play Store).</p>\n  </div>\n</div>\n\n<div class=\"drawer-overlay\" id=\"prefOverlay\">\n  <div class=\"drawer\" id=\"prefDrawer\">\n    <div class=\"drawer-handle\"></div>\n    <div class=\"drawer-head\">\n      <h3>Mes préférences</h3>\n      <button class=\"drawer-close\" id=\"prefClose\">✕</button>\n    </div>\n    <p class=\"drawer-note\">Coche ce qui t'intéresse — l'appli ouvrira ces catégories par défaut. Sans préférence cochée, elle se base sur ce que tu ouvres le plus souvent.</p>\n    <div id=\"prefList\"></div>\n  </div>\n</div>\n\n<script>\n(function () {\n  var PAY_LABEL = { faible: 'Gain faible', moyen: 'Gain moyen', eleve: 'Gain élevé' };\n  var TIME_LABEL = { rapide: '⚡ Rapide', moyen: '🕰 Moyen', long: '🕰 Long' };\n  var CAT_LABEL = { vetement: 'Vêtement', cuisine: 'Cuisine & alim.', outils: 'Outils & jardin', sponsoring: 'Sponsoring' };\n\n  var surveys = [\n    { id: 'toluna', name: 'Toluna Influencers', url: 'https://www.toluna.com', payout: 'moyen', payoutLabel: 'Points, variable', time: 'moyen', desc: 'Panel généraliste très actif, sondages courts à moyens, gains en points convertibles.' },\n    { id: 'lifepoints', name: 'LifePoints', url: 'https://www.lifepoints.com', payout: 'moyen', payoutLabel: 'Dès 5 €', time: 'moyen', desc: 'Seuil de retrait plus élevé mais missions régulières et bien cadrées.' },\n    { id: 'ipsos', name: 'IPSOS i-Say', url: 'https://www.ipsos.com/fr-fr/i-say', payout: 'faible', payoutLabel: 'Dès 2 €', time: 'rapide', desc: 'Sondages courts d’opinion générale, fréquence correcte.' },\n    { id: 'primeopinion', name: 'Prime Opinion', url: 'https://prime-opinion.com', payout: 'eleve', payoutLabel: 'Nettement au-dessus de la moyenne', time: 'long', desc: 'Cible les profils pro difficiles à trouver — sondages plus longs mais bien mieux payés.' },\n    { id: 'mobrog', name: 'Mobrog', url: 'https://www.mobrog.com', payout: 'faible', payoutLabel: '0,50 – 2 €', payoutMin: 0.5, payoutMax: 2, time: 'rapide', desc: 'Beaucoup de petites missions rapides, présent dans 60+ pays.' },\n    { id: 'gaddin', name: 'Gaddin', url: 'https://www.gaddin.fr', payout: 'moyen', payoutLabel: '1 – 5 € / mission', payoutMin: 1, payoutMax: 5, time: 'moyen', desc: 'Missions variées, bon compromis temps / rémunération pour la Belgique.' },\n    { id: 'opinionz', name: 'Opinionz', url: 'https://www.opinionz.eu', payout: 'faible', payoutLabel: '0,20 – 1 €', payoutMin: 0.2, payoutMax: 1, time: 'rapide', desc: 'Sondages très courts, idéal pour cumuler entre deux tâches.' },\n    { id: 'swagbucks', name: 'Swagbucks', url: 'https://www.swagbucks.com', payout: 'faible', payoutLabel: '0,50 – 2,50 €', payoutMin: 0.5, payoutMax: 2.5, time: 'rapide', desc: 'Sondages courts + petites tâches annexes cumulables.' },\n    { id: 'testapic', name: 'Testapic', url: 'https://www.testapic.com', payout: 'eleve', payoutLabel: '10 – 50 € / test', payoutMin: 10, payoutMax: 50, time: 'moyen', desc: 'Test utilisateur sur des sites/apps en France : tu navigues à voix haute, 15-30 min, bien mieux payé qu’un sondage classique.' },\n    { id: 'usertesting', name: 'UserTesting', url: 'https://www.usertesting.com', payout: 'moyen', payoutLabel: 'Variable, affiché avant d’accepter', time: 'moyen', desc: 'Plateforme internationale de tests utilisateurs, 15-20 min en général, montant visible avant de commencer.' }\n  ];\n\n  var international = [\n    { id: 'prolific', name: 'Prolific', url: 'https://www.prolific.com', pay: '6 – 10 £ / heure', time: '5 – 20 min par étude', avail: 'Éligibilité internationale large', desc: 'Études pour chercheurs et entreprises, en anglais — considérée comme l’une des mieux payées et des plus fiables du secteur.' },\n    { id: 'surveyjunkie', name: 'Survey Junkie', url: 'https://www.surveyjunkie.com', pay: '0,50 – 40 $ / sondage', time: 'Variable', avail: 'US · Canada · Australie', desc: 'Grand panel bien établi, sondages en anglais de durées et de gains très variés.' },\n    { id: 'brandedsurveys', name: 'Branded Surveys', url: 'https://www.brandedsurveys.com', pay: '0,50 – 25 $ / sondage', time: 'Variable', avail: 'US · UK · Canada · Australie', desc: 'Sondages d’opinion en anglais avec un système de points cumulables en plus du cash.' },\n    { id: 'pineconeresearch', name: 'Pinecone Research', url: 'https://www.pineconeresearch.com', pay: 'Tarif fixe, souvent 3 $+', time: '10 – 20 min', avail: 'US · Canada · UK · Allemagne', desc: 'Places sur invitation, ouvertes par vagues — rémunération fixe par sondage en anglais, pas de tirage au sort.' },\n    { id: 'yougov', name: 'YouGov', url: 'https://yougov.com', pay: 'Points convertibles en argent/bons d’achat', time: '5 – 15 min', avail: 'Disponible dans de nombreux pays', desc: 'Panel international d’opinion et d’études de marché, en anglais, derrière de nombreux sondages publics connus.' }\n  ];\n\n  var cashback = [\n    { id: 'igraal', name: 'iGraal', url: 'https://www.igraal.com', icon: '🛒', desc: 'Cashback sur tes achats en ligne habituels, reversé en argent ou bon d’achat.', avail: 'FR · BE' },\n    { id: 'shopmium', name: 'Shopmium', url: 'https://www.shopmium.com', icon: '🧾', desc: 'Remboursement sur des produits précis en supermarché, scan du ticket de caisse.', avail: 'FR · BE' },\n    { id: 'poulpeo', name: 'Poulpeo', url: 'https://www.poulpeo.com', icon: '💶', desc: 'Cashback sur des milliers de sites marchands, cumulable avec les promos.', avail: 'FR — à vérifier en BE' }\n  ];\n\n  var trials = [\n    { id: 'easydresscode', name: 'Easy Dress Code', url: 'https://www.easydresscode.com/vetements-gratuits', cat: 'vetement', desc: 'Vêtements de marques partenaires envoyés gratuitement, à garder.', select: 'Sélection sur profil · avis à publier' },\n    { id: 'shein', name: 'SHEIN Free Trial', url: 'https://m.shein.com/fr/Free-Trial-Hel-Center-a-747.html', cat: 'vetement', desc: 'Pièces sélectionnées dans l’appli contre avis et photo.', select: 'Sélection dans l’appli · avis + photo' },\n    { id: 'leseclaireuses', name: 'Les Éclaireuses', url: 'https://www.leseclaireuses.com', cat: 'vetement', desc: 'Communauté de testeuses mode, beauté et bien-être.', select: 'Campagnes par vagues' },\n    { id: 'skeeper', name: 'Skeeper', url: 'https://www.skeeper.com', cat: 'cuisine', desc: 'Petit électroménager de cuisine, hygiène et alimentaire.', select: 'Campagnes par vagues selon profil' },\n    { id: 'hometester', name: 'HomeTester Club', url: 'https://www.hometesterclub.com', cat: 'cuisine', desc: 'Colis réguliers : alimentaire, hygiène, maison, bébé.', select: 'Communauté élargie · avis demandé' },\n    { id: 'trnd', name: 'TRND', url: 'https://www.trnd.com/fr', cat: 'cuisine', desc: 'Campagnes de grandes marques alimentaires et boissons.', select: 'Sélection par campagne' },\n    { id: 'bricozor', name: 'Bricozor — Team Testeurs', url: 'https://comptoir.bricozor.com/team-testeurs-bricozor.html', cat: 'outils', desc: 'Outillage et matériel de bricolage/jardin à tester chez toi.', select: 'Candidature testeur dédiée' },\n    { id: 'leroymerlin', name: 'Club Testeurs Leroy Merlin', url: 'https://www.leroymerlin.fr', cat: 'outils', desc: 'Outillage, jardin et parfois petit équipement de cuisine.', select: 'Ateliers et sélections ponctuelles' },\n    { id: 'sampleo', name: 'Sampleo', url: 'https://www.sampleo.com/fr/', cat: 'sponsoring', desc: 'Programme d’ambassadeurs : échantillons multi-catégories contre avis suivi.', select: 'Statut ambassadeur · profil actif' },\n    { id: 'influenster', name: 'Influenster', url: 'https://www.influenster.com/fr', cat: 'sponsoring', desc: 'VoxBox thématiques : beauté, maison, tech, alimentaire, à l’international.', select: 'Sélection algorithmique par profil' },\n    { id: 'insiders', name: 'The Insiders', url: 'https://www.theinsiders.com', cat: 'sponsoring', desc: 'Missions de marque avec brief, hygiène/maison/beauté surtout.', select: 'Campagnes par vagues' }\n  ];\n\n  var state = { survey: {}, trial: {}, filterS: 'tous', filterE: 'tous' };\n  var STORAGE_KEY = 'duo-testeur-state-v1';\n\n  function loadState() {\n    try {\n      var raw = localStorage.getItem(STORAGE_KEY);\n      if (raw) {\n        var parsed = JSON.parse(raw);\n        state.survey = parsed.survey || {};\n        state.trial = parsed.trial || {};\n      }\n    } catch (e) { /* ignore */ }\n  }\n\n  function saveState() {\n    try {\n      localStorage.setItem(STORAGE_KEY, JSON.stringify({ survey: state.survey, trial: state.trial }));\n    } catch (e) { /* ignore */ }\n  }\n\n  function payVars(tier) {\n    return { bar: 'var(--pay-' + tier + ')', soft: 'var(--pay-' + tier + '-soft)' };\n  }\n  function catVars(cat) {\n    return { bar: 'var(--cat-' + cat + ')', soft: 'var(--cat-' + cat + '-soft)' };\n  }\n\n  function matchesSurveyFilter(item, f) {\n    if (f === 'tous') return true;\n    if (f === 'rapide') return item.time === 'rapide';\n    if (f === 'eleve') return item.payout === 'eleve';\n    if (f === 'rapide-eleve') return item.time === 'rapide' && item.payout === 'eleve';\n    return true;\n  }\n\n  function renderSurveys() {\n    var list = document.getElementById('listSondages');\n    var filtered = surveys.filter(function (s) { return matchesSurveyFilter(s, state.filterS); });\n    if (!filtered.length) {\n      list.innerHTML = '<div class=\"empty-state\">Aucune plateforme dans cette combinaison — les sondages à la fois rapides et très bien payés sont rares, c’est le compromis classique de ce secteur. Essaie \"Bien payé\" ou \"Rapide\" séparément.</div>';\n      return;\n    }\n    list.innerHTML = filtered.map(function (s) {\n      var v = payVars(s.payout);\n      var done = !!state.survey[s.id];\n      return '' +\n        '<div class=\"card\">' +\n          '<div class=\"card-bar\" style=\"background:' + v.bar + '\"></div>' +\n          '<div class=\"card-main\">' +\n            '<div class=\"card-top\">' +\n              '<h3 class=\"card-title\">' + s.name + (isPremiumUnlocked() && PREMIUM_IDS.indexOf(s.id) !== -1 ? '<span class=\"premium-flag\">⭐ Premium</span>' : '') + '</h3>' +\n              '<button class=\"check-btn' + (done ? ' done' : '') + '\" data-kind=\"survey\" data-id=\"' + s.id + '\">' + (done ? '✓' : '') + '</button>' +\n            '</div>' +\n            '<p class=\"card-desc\">' + s.desc + '</p>' +\n            '<div class=\"badge-row\">' +\n              '<span class=\"badge\" style=\"background:' + v.soft + ';color:' + v.bar + '\">' + PAY_LABEL[s.payout] + ' · ' + s.payoutLabel + '</span>' +\n              '<span class=\"badge\" style=\"background:var(--surface-2);color:var(--ink-soft)\">' + TIME_LABEL[s.time] + '</span>' +\n            '</div>' +\n            '<div class=\"card-foot\">' +\n              '<span></span>' +\n              '<a class=\"open-btn\" href=\"' + s.url + '\" target=\"_blank\" rel=\"noopener\">Ouvrir →</a>' +\n            '</div>' +\n          '</div>' +\n        '</div>';\n    }).join('');\n  }\n\n  function renderTrials() {\n    var list = document.getElementById('listEssais');\n    var filtered = trials.filter(function (t) { return state.filterE === 'tous' || t.cat === state.filterE; });\n    if (!filtered.length) {\n      list.innerHTML = '<div class=\"empty-state\">Rien dans cette catégorie pour le moment.</div>';\n      return;\n    }\n    list.innerHTML = filtered.map(function (t) {\n      var v = catVars(t.cat);\n      var done = !!state.trial[t.id];\n      return '' +\n        '<div class=\"card\" data-cat=\"' + t.cat + '\">' +\n          '<div class=\"card-bar\" style=\"background:' + v.bar + '\"></div>' +\n          '<div class=\"card-main\">' +\n            '<div class=\"card-top\">' +\n              '<h3 class=\"card-title\">' + t.name + '</h3>' +\n              '<button class=\"check-btn' + (done ? ' done' : '') + '\" data-kind=\"trial\" data-id=\"' + t.id + '\">' + (done ? '✓' : '') + '</button>' +\n            '</div>' +\n            '<p class=\"card-desc\">' + t.desc + '</p>' +\n            '<div class=\"badge-row\">' +\n              '<span class=\"badge\" style=\"background:' + v.soft + ';color:' + v.bar + '\">' + CAT_LABEL[t.cat] + '</span>' +\n            '</div>' +\n            '<div class=\"card-foot\">' +\n              '<span class=\"select-note\">' + t.select + '</span>' +\n              '<a class=\"open-btn\" href=\"' + t.url + '\" target=\"_blank\" rel=\"noopener\">Ouvrir →</a>' +\n            '</div>' +\n          '</div>' +\n        '</div>';\n    }).join('');\n  }\n\n  function seededFrac(seed) {\n    var x = Math.sin(seed) * 10000;\n    return x - Math.floor(x);\n  }\n\n  function seededIndex(seed, mod) {\n    return Math.floor(seededFrac(seed) * mod);\n  }\n\n  function dateSeed() {\n    var d = new Date();\n    return d.getFullYear() * 372 + (d.getMonth() + 1) * 31 + d.getDate();\n  }\n\n  function formatEuro(n) {\n    var s = n.toFixed(2).replace('.', ',');\n    return s.replace(',00', '');\n  }\n\n  function pickCombos(seed, count) {\n    var closedSurveys = surveys.filter(function (s) { return typeof s.payoutMin === 'number'; });\n    var pairs = [];\n    for (var i = 0; i < closedSurveys.length; i++) {\n      for (var j = i + 1; j < closedSurveys.length; j++) {\n        pairs.push([closedSurveys[i], closedSurveys[j]]);\n      }\n    }\n    var combos = [];\n    var usedPairs = {};\n    for (var k = 0; k < count; k++) {\n      var pairIdx = seededIndex(seed + k * 7.13, pairs.length);\n      var tries = 0;\n      while (usedPairs[pairIdx] && tries < pairs.length) {\n        pairIdx = (pairIdx + 1) % pairs.length;\n        tries++;\n      }\n      usedPairs[pairIdx] = true;\n      var trialIdx = seededIndex(seed + k * 3.31 + 1, trials.length);\n      combos.push({ surveyA: pairs[pairIdx][0], surveyB: pairs[pairIdx][1], trial: trials[trialIdx] });\n    }\n    return combos;\n  }\n\n  function renderOffres(seed) {\n    var list = document.getElementById('listOffres');\n    var countEl = document.getElementById('offresCount');\n    var combos = pickCombos(seed, 2);\n    if (countEl) {\n      countEl.textContent = combos.length + ' cumuls suggérés aujourd’hui';\n    }\n    list.innerHTML = combos.map(function (c, idx) {\n      var min = c.surveyA.payoutMin + c.surveyB.payoutMin;\n      var max = c.surveyA.payoutMax + c.surveyB.payoutMax;\n      var itemsHtml = [c.surveyA, c.surveyB].map(function (s) {\n        return '' +\n          '<div class=\"combo-item-row\">' +\n            '<div class=\"combo-item-info\">' +\n              '<span class=\"combo-item-name\">' + s.name + '</span>' +\n              '<span class=\"combo-item-meta\">' + s.payoutLabel + ' · ' + TIME_LABEL[s.time] + '</span>' +\n            '</div>' +\n            '<a class=\"combo-item-link\" href=\"' + s.url + '\" target=\"_blank\" rel=\"noopener\">Ouvrir</a>' +\n          '</div>';\n      }).join('');\n      var trialRow = '' +\n        '<div class=\"combo-item-row\">' +\n          '<div class=\"combo-item-info\">' +\n            '<span class=\"combo-item-name\">' + c.trial.name + '</span>' +\n            '<span class=\"combo-item-meta\">' + CAT_LABEL[c.trial.cat] + ' · produit à garder</span>' +\n          '</div>' +\n          '<a class=\"combo-item-link\" href=\"' + c.trial.url + '\" target=\"_blank\" rel=\"noopener\">Ouvrir</a>' +\n        '</div>';\n      return '' +\n        '<div class=\"combo-card\">' +\n          '<h3 class=\"combo-title\">✨ Cumul suggéré ' + (idx + 1) + '</h3>' +\n          itemsHtml + trialRow +\n          '<div class=\"total-line\">' +\n            '<span class=\"total-label\">Argent cumulé (2 sondages, fourchette annoncée)</span>' +\n            '<span class=\"total-amount\">' + formatEuro(min) + ' – ' + formatEuro(max) + ' €</span>' +\n          '</div>' +\n          '<div class=\"product-line\">+ un article ' + CAT_LABEL[c.trial.cat].toLowerCase() + ' reçu gratuitement, à garder — valeur non chiffrée ici</div>' +\n        '</div>';\n    }).join('');\n\n    var cashbackHtml = '' +\n      '<div class=\"offres-divider\">Économies automatiques</div>' +\n      '<p class=\"cashback-note\">Pas de temps en plus à prévoir : une partie de tes achats déjà prévus (courses, sites en ligne) te revient en argent ou en bon d’achat.</p>' +\n      cashback.map(function (cb) {\n        return '' +\n          '<div class=\"cashback-card\">' +\n            '<div class=\"cashback-icon\">' + cb.icon + '</div>' +\n            '<div class=\"cashback-body\">' +\n              '<div class=\"cashback-name\">' + cb.name + '</div>' +\n              '<div class=\"cashback-desc\">' + cb.desc + '</div>' +\n              '<div class=\"cashback-avail\">' + cb.avail + '</div>' +\n            '</div>' +\n            '<a class=\"open-btn\" href=\"' + cb.url + '\" target=\"_blank\" rel=\"noopener\">Ouvrir →</a>' +\n          '</div>';\n      }).join('');\n\n    list.innerHTML += cashbackHtml;\n  }\n\n  function bindCardEvents() {\n    document.querySelectorAll('.check-btn').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var kind = btn.getAttribute('data-kind');\n        var id = btn.getAttribute('data-id');\n        var bucket = kind === 'survey' ? state.survey : state.trial;\n        bucket[id] = !bucket[id];\n        saveState();\n        if (kind === 'survey') renderSurveys(); else renderTrials();\n        bindCardEvents();\n      });\n    });\n  }\n\n  function switchTab(tab) {\n    document.getElementById('tabSondages').classList.toggle('active', tab === 'sondages');\n    document.getElementById('tabEssais').classList.toggle('active', tab === 'essais');\n    document.getElementById('tabOffres').classList.toggle('active', tab === 'offres');\n    document.getElementById('tabIntl').classList.toggle('active', tab === 'intl');\n    document.querySelectorAll('.tab-btn').forEach(function (b) {\n      b.classList.toggle('active', b.getAttribute('data-tab') === tab);\n    });\n\n    document.getElementById('tierBox').style.display = tab === 'sondages' ? 'block' : 'none';\n    document.getElementById('legendSondages').style.display = tab === 'sondages' ? 'flex' : 'none';\n    document.getElementById('legendEssais').style.display = tab === 'essais' ? 'flex' : 'none';\n    document.getElementById('chipsSondages').style.display = tab === 'sondages' ? 'flex' : 'none';\n    document.getElementById('chipsEssais').style.display = tab === 'essais' ? 'flex' : 'none';\n    document.getElementById('infoOffres').style.display = tab === 'offres' ? 'block' : 'none';\n    document.getElementById('shuffleRowOffres').style.display = tab === 'offres' ? 'flex' : 'none';\n\n    document.getElementById('listSondages').style.display = tab === 'sondages' ? 'flex' : 'none';\n    document.getElementById('listEssais').style.display = tab === 'essais' ? 'flex' : 'none';\n    document.getElementById('listOffres').style.display = tab === 'offres' ? 'flex' : 'none';\n    document.getElementById('listIntl').style.display = tab === 'intl' ? 'flex' : 'none';\n    if (tab === 'intl') renderIntl();\n  }\n\n  /* ---------- Garantie 45 jours ---------- */\n  var INSTALL_KEY = 'duo-testeur-install-date';\n\n  function getInstallDate() {\n    try {\n      var v = localStorage.getItem(INSTALL_KEY);\n      if (!v) {\n        v = new Date().toISOString().slice(0, 10);\n        localStorage.setItem(INSTALL_KEY, v);\n      }\n      return v;\n    } catch (e) {\n      return new Date().toISOString().slice(0, 10);\n    }\n  }\n\n  function daysBetween(d1, d2) {\n    var a = new Date(d1 + 'T00:00:00');\n    var b = new Date(d2 + 'T00:00:00');\n    return Math.round((b - a) / 86400000);\n  }\n\n  function renderGuarantee() {\n    var install = getInstallDate();\n    var today = new Date().toISOString().slice(0, 10);\n    var dayNum = Math.min(Math.max(daysBetween(install, today), 0), 45);\n    var installD = new Date(install + 'T00:00:00');\n    var windowEnd = new Date(installD);\n    windowEnd.setDate(windowEnd.getDate() + 45);\n\n    var totalInWindow = loadEntries().reduce(function (sum, e) {\n      if (!e.date) return sum;\n      var d = new Date(e.date + 'T00:00:00');\n      return (d >= installD && d <= windowEnd) ? sum + e.amount : sum;\n    }, 0);\n\n    var totalStr = totalInWindow.toFixed(2).replace('.', ',') + ' €';\n    var el = document.getElementById('guaranteeBanner');\n    var expired = daysBetween(install, today) > 45;\n\n    if (totalInWindow >= 1.5) {\n      el.className = 'guarantee-banner positive';\n      el.innerHTML = '✅ Achat rentabilisé : <strong>' + totalStr + '</strong> encaissés depuis l’installation.';\n    } else if (!expired) {\n      el.className = 'guarantee-banner';\n      el.innerHTML = '🛡️ Garantie 45 jours · jour ' + dayNum + '/45 — toujours rien encaissé au jour 45 ? Le prix de l’app t’est remboursé.';\n    } else {\n      el.className = 'guarantee-banner';\n      el.innerHTML = '🛡️ 45 jours écoulés sans encaissement — remboursement disponible, contacte le support avec ton suivi.';\n    }\n  }\n\n  /* ---------- Palier de fidélité ---------- */\n  var TIERS = [\n    { name: 'Débutant·e', min: 0 },\n    { name: 'Actif·ve', min: 7 },\n    { name: 'Premium', min: 15 }\n  ];\n  var PREMIUM_IDS = ['testapic', 'usertesting', 'primeopinion'];\n  var PREMIUM_PAID_KEY = 'duo-testeur-premium-paid';\n\n  function lifetimeSurveyCount() {\n    return loadEntries().filter(function (e) { return SURVEY_NAMES.indexOf(e.source) !== -1; }).length;\n  }\n\n  function isPremiumPaid() {\n    try { return localStorage.getItem(PREMIUM_PAID_KEY) === '1'; } catch (e) { return false; }\n  }\n\n  function setPremiumPaid() {\n    try { localStorage.setItem(PREMIUM_PAID_KEY, '1'); } catch (e) { /* ignore */ }\n  }\n\n  function isPremiumUnlocked() {\n    return lifetimeSurveyCount() >= TIERS[TIERS.length - 1].min || isPremiumPaid();\n  }\n\n  var PREMIUM_PLUS_PAID_KEY = 'duo-testeur-premium-plus-paid';\n\n  function isPremiumPlusUnlocked() {\n    try { return localStorage.getItem(PREMIUM_PLUS_PAID_KEY) === '1'; } catch (e) { return false; }\n  }\n\n  function setPremiumPlusPaid() {\n    try { localStorage.setItem(PREMIUM_PLUS_PAID_KEY, '1'); } catch (e) { /* ignore */ }\n  }\n\n  function renderIntl() {\n    var list = document.getElementById('listIntl');\n    if (!isPremiumPlusUnlocked()) {\n      list.innerHTML = '' +\n        '<div class=\"paywall-card\">' +\n          '<h3>🌍 Sondages internationaux</h3>' +\n          '<p>Une sélection de panels anglophones bien rémunérés, disponibles partout dans le monde. Les sondages eux-mêmes restent en anglais — on ne peut pas les traduire, ils sont générés en direct par chaque plateforme — mais tout le reste de cet onglet est en français.</p>' +\n          '<div class=\"paywall-preview\"><span>Prolific</span><span>Survey Junkie</span><span>Branded Surveys</span><span>Pinecone Research</span><span>YouGov</span></div>' +\n          '<button class=\"paywall-btn\" id=\"unlockIntlBtn\">Débloquer — 2,99 €</button>' +\n          '<p class=\"paywall-honest\">Ces plateformes restent gratuites pour tout le monde sur leur propre site — tu payes le tri, pas un accès fermé.</p>' +\n        '</div>';\n      var btn = list.querySelector('#unlockIntlBtn');\n      if (btn) btn.addEventListener('click', function () {\n        document.getElementById('premiumPlusOverlay').classList.add('open');\n      });\n      return;\n    }\n\n    list.innerHTML = international.map(function (p) {\n      return '' +\n        '<div class=\"card\">' +\n          '<div class=\"card-bar\" style=\"background:var(--cat-sponsor)\"></div>' +\n          '<div class=\"card-main\">' +\n            '<div class=\"card-top\">' +\n              '<h3 class=\"card-title\">' + p.name + '</h3>' +\n            '</div>' +\n            '<p class=\"card-desc\">' + p.desc + '</p>' +\n            '<div class=\"badge-row\">' +\n              '<span class=\"badge\" style=\"background:var(--cat-sponsor-soft);color:var(--cat-sponsor)\">' + p.pay + '</span>' +\n              '<span class=\"badge\" style=\"background:var(--surface-2);color:var(--ink-soft)\">' + p.time + '</span>' +\n            '</div>' +\n            '<div class=\"card-foot\">' +\n              '<span class=\"select-note\">' + p.avail + '</span>' +\n              '<a class=\"open-btn\" href=\"' + p.url + '\" target=\"_blank\" rel=\"noopener\">Ouvrir →</a>' +\n            '</div>' +\n          '</div>' +\n        '</div>';\n    }).join('');\n  }\n\n  function renderTier() {\n    var count = lifetimeSurveyCount();\n    var paid = isPremiumPaid();\n    var current = TIERS[0];\n    for (var i = 0; i < TIERS.length; i++) { if (count >= TIERS[i].min) current = TIERS[i]; }\n    var next = TIERS[TIERS.indexOf(current) + 1];\n    var box = document.getElementById('tierBox');\n\n    if (!next || paid) {\n      box.innerHTML = '' +\n        '<div class=\"tier-head\"><span class=\"tier-name\">⭐ Palier Premium' + (paid && !(!next) ? ' (débloqué)' : '') + '</span><span class=\"tier-count\">' + count + ' réponses</span></div>' +\n        '<div class=\"tier-track\"><div class=\"tier-fill\" style=\"width:100%\"></div></div>' +\n        '<div class=\"tier-celebrate\">Sélection Premium débloquée — Testapic, UserTesting et Prime Opinion sont mis en avant, et l’interface se personnalise pour toi.</div>';\n    } else {\n      var progress = Math.min(100, Math.round(((count - current.min) / (next.min - current.min)) * 100));\n      box.innerHTML = '' +\n        '<div class=\"tier-head\"><span class=\"tier-name\">Palier ' + current.name + '</span><span class=\"tier-count\">' + count + ' / ' + next.min + ' réponses</span></div>' +\n        '<div class=\"tier-track\"><div class=\"tier-fill\" style=\"width:' + progress + '%\"></div></div>' +\n        '<button class=\"skip-btn\" id=\"skipPremiumBtn\">⚡ Passer direct au Premium — 1,00 €</button>';\n      var skipBtn = box.querySelector('#skipPremiumBtn');\n      if (skipBtn) skipBtn.addEventListener('click', function () {\n        document.getElementById('premiumOverlay').classList.add('open');\n      });\n    }\n  }\n\n  /* ---------- Préférences & personnalisation ---------- */\n  var PREF_KEY = 'duo-testeur-prefs-v1';\n  var USAGE_KEY = 'duo-testeur-usage-v1';\n  var PREF_OPTIONS = [\n    { id: 'sondages', label: 'Sondages & tests rémunérés' },\n    { id: 'vetement', label: 'Essais vêtement' },\n    { id: 'cuisine', label: 'Essais cuisine & alimentation' },\n    { id: 'outils', label: 'Essais outils & jardin' },\n    { id: 'sponsoring', label: 'Essais sponsoring / ambassadeur' }\n  ];\n\n  function loadPrefs() {\n    try { return JSON.parse(localStorage.getItem(PREF_KEY) || '{}'); } catch (e) { return {}; }\n  }\n  function savePrefs(p) { try { localStorage.setItem(PREF_KEY, JSON.stringify(p)); } catch (e) { /* ignore */ } }\n  function loadUsage() {\n    try { return JSON.parse(localStorage.getItem(USAGE_KEY) || '{}'); } catch (e) { return {}; }\n  }\n  function bumpUsage(key) {\n    var u = loadUsage();\n    u[key] = (u[key] || 0) + 1;\n    try { localStorage.setItem(USAGE_KEY, JSON.stringify(u)); } catch (e) { /* ignore */ }\n  }\n\n  function renderPrefList() {\n    var prefs = loadPrefs();\n    var list = document.getElementById('prefList');\n    var lockedNote = !isPremiumUnlocked()\n      ? '<p class=\"pref-hint\">🔒 La personnalisation s’active au palier Premium (15 sondages répondus, ou déblocage à 1 €). Tu peux déjà régler tes préférences, elles s’appliqueront dès que tu l’atteins.</p>'\n      : '<p class=\"pref-hint\">Aucune case cochée : l’appli s’adapte automatiquement à ce que tu ouvres le plus souvent.</p>';\n    list.innerHTML = PREF_OPTIONS.map(function (opt) {\n      var checked = prefs[opt.id] ? 'checked' : '';\n      return '<div class=\"pref-option\"><input type=\"checkbox\" id=\"pref-' + opt.id + '\" data-pref=\"' + opt.id + '\" ' + checked + '><label for=\"pref-' + opt.id + '\">' + opt.label + '</label></div>';\n    }).join('') + lockedNote;\n\n    list.querySelectorAll('input[type=checkbox]').forEach(function (cb) {\n      cb.addEventListener('change', function () {\n        var p = loadPrefs();\n        p[cb.getAttribute('data-pref')] = cb.checked;\n        savePrefs(p);\n        applyPersonalization(false);\n      });\n    });\n  }\n\n  function preferredEssaiCategory() {\n    if (!isPremiumUnlocked()) return 'tous';\n    var prefs = loadPrefs();\n    var cats = ['vetement', 'cuisine', 'outils', 'sponsoring'];\n    var chosen = cats.filter(function (c) { return prefs[c]; });\n    if (chosen.length === 1) return chosen[0];\n    if (chosen.length > 1) return 'tous';\n\n    var usage = loadUsage();\n    var best = 'tous', bestVal = 2; // needs at least 3 uses before auto-adapting\n    cats.forEach(function (c) {\n      var v = usage['cat_' + c] || 0;\n      if (v > bestVal) { bestVal = v; best = c; }\n    });\n    return best;\n  }\n\n  function applyPersonalization(initial) {\n    var cat = preferredEssaiCategory();\n    state.filterE = cat;\n    document.querySelectorAll('#chipsEssais .chip').forEach(function (c) {\n      c.classList.toggle('active', c.getAttribute('data-filter') === cat);\n    });\n    renderTrials();\n    bindCardEvents();\n\n    if (initial && isPremiumUnlocked()) {\n      var prefs = loadPrefs();\n      var essaiCats = ['vetement', 'cuisine', 'outils', 'sponsoring'];\n      var wantsEssaiOnly = essaiCats.some(function (c) { return prefs[c]; }) && !prefs.sondages;\n      var wantsSondagesOnly = prefs.sondages && !essaiCats.some(function (c) { return prefs[c]; });\n      if (wantsEssaiOnly) switchTab('essais');\n      else if (wantsSondagesOnly) switchTab('sondages');\n    }\n  }\n\n  var TRACKER_KEY = 'duo-testeur-tracker-v1';\n\n  function loadEntries() {\n    try {\n      var raw = localStorage.getItem(TRACKER_KEY);\n      return raw ? JSON.parse(raw) : [];\n    } catch (e) { return []; }\n  }\n\n  function saveEntries(entries) {\n    try { localStorage.setItem(TRACKER_KEY, JSON.stringify(entries)); } catch (e) { /* ignore */ }\n  }\n\n  function isThisMonth(dateStr) {\n    if (!dateStr) return true;\n    var d = new Date(dateStr + 'T00:00:00');\n    var now = new Date();\n    return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth();\n  }\n\n  var SURVEY_NAMES = surveys.map(function (s) { return s.name; });\n  var TRIAL_NAMES = trials.map(function (t) { return t.name; });\n\n  function renderChart(monthEntriesSorted) {\n    var container = document.getElementById('chartContainer');\n    if (monthEntriesSorted.length < 2) {\n      container.innerHTML = '<div class=\"chart-empty\">Ajoute au moins deux gains ce mois-ci pour voir ta courbe de progression se dessiner.</div>';\n      return;\n    }\n\n    var running = 0;\n    var points = monthEntriesSorted.map(function (e, i) {\n      running += e.amount;\n      return { idx: i + 1, cumul: running, source: e.source };\n    });\n\n    var W = 320, H = 150, padL = 34, padR = 14, padT = 14, padB = 22;\n    var innerW = W - padL - padR, innerH = H - padT - padB;\n    var maxY = points[points.length - 1].cumul * 1.12 || 1;\n    var n = points.length;\n\n    function xAt(i) { return padL + (n === 1 ? innerW / 2 : (i / (n - 1)) * innerW); }\n    function yAt(v) { return padT + innerH - (v / maxY) * innerH; }\n\n    var linePts = points.map(function (p, i) { return xAt(i) + ',' + yAt(p.cumul).toFixed(1); }).join(' L ');\n    var lineD = 'M ' + linePts;\n    var areaD = lineD + ' L ' + xAt(n - 1) + ',' + (padT + innerH) + ' L ' + xAt(0) + ',' + (padT + innerH) + ' Z';\n\n    var gridLines = [0, 0.5, 1].map(function (f) {\n      var y = padT + innerH * (1 - f);\n      var val = maxY * f;\n      return '<line x1=\"' + padL + '\" y1=\"' + y + '\" x2=\"' + (W - padR) + '\" y2=\"' + y + '\" stroke=\"var(--line)\" stroke-width=\"1\"/>' +\n        '<text x=\"' + (padL - 6) + '\" y=\"' + (y + 3) + '\" text-anchor=\"end\" font-size=\"8\" font-family=\"IBM Plex Mono, monospace\" fill=\"var(--ink-faint)\">' + Math.round(val) + '€</text>';\n    }).join('');\n\n    var last = points[n - 1];\n    var endLabel = '<text x=\"' + xAt(n - 1) + '\" y=\"' + (yAt(last.cumul) - 10) + '\" text-anchor=\"end\" font-size=\"9.5\" font-weight=\"700\" font-family=\"Sora, sans-serif\" fill=\"var(--ink)\">' +\n      last.cumul.toFixed(2).replace('.', ',') + ' €</text>';\n\n    var svg = '' +\n      '<svg viewBox=\"0 0 ' + W + ' ' + H + '\" width=\"100%\" height=\"150\" id=\"gainSvg\" style=\"overflow:visible;touch-action:pan-y\">' +\n        gridLines +\n        '<path d=\"' + areaD + '\" style=\"fill:var(--pay-eleve);fill-opacity:0.12;stroke:none\"/>' +\n        '<path d=\"' + lineD + '\" style=\"fill:none;stroke:var(--pay-eleve);stroke-width:2;stroke-linejoin:round;stroke-linecap:round\"/>' +\n        '<circle cx=\"' + xAt(n - 1) + '\" cy=\"' + yAt(last.cumul) + '\" r=\"5\" style=\"fill:var(--pay-eleve);stroke:var(--bg);stroke-width:2\"/>' +\n        endLabel +\n        '<line id=\"crosshair\" x1=\"0\" y1=\"' + padT + '\" x2=\"0\" y2=\"' + (padT + innerH) + '\" stroke=\"var(--ink-faint)\" stroke-width=\"1\" opacity=\"0\"/>' +\n      '</svg>' +\n      '<div class=\"chart-tooltip\" id=\"chartTooltip\"><span class=\"val\"></span></div>';\n\n    container.innerHTML = '<div class=\"chart-svg-wrap\">' + svg + '</div>';\n\n    var svgEl = document.getElementById('gainSvg');\n    var crosshair = document.getElementById('crosshair');\n    var tooltip = document.getElementById('chartTooltip');\n\n    function showAt(clientX) {\n      var rect = svgEl.getBoundingClientRect();\n      var relX = ((clientX - rect.left) / rect.width) * W;\n      var nearest = 0, best = Infinity;\n      for (var i = 0; i < n; i++) {\n        var d = Math.abs(xAt(i) - relX);\n        if (d < best) { best = d; nearest = i; }\n      }\n      var p = points[nearest];\n      crosshair.setAttribute('x1', xAt(nearest));\n      crosshair.setAttribute('x2', xAt(nearest));\n      crosshair.setAttribute('opacity', '1');\n      var pxRatio = rect.width / W;\n      tooltip.style.left = (xAt(nearest) * pxRatio) + 'px';\n      tooltip.style.top = (yAt(p.cumul) * (rect.height / H)) + 'px';\n      tooltip.querySelector('.val').textContent = 'Activité n°' + p.idx + ' — ' + p.cumul.toFixed(2).replace('.', ',') + ' € · ' + p.source;\n      tooltip.classList.add('show');\n    }\n\n    function hide() {\n      crosshair.setAttribute('opacity', '0');\n      tooltip.classList.remove('show');\n    }\n\n    svgEl.addEventListener('pointermove', function (ev) { showAt(ev.clientX); });\n    svgEl.addEventListener('pointerdown', function (ev) { showAt(ev.clientX); });\n    svgEl.addEventListener('pointerleave', hide);\n  }\n\n  var MONTH_ABBR = ['janv.', 'févr.', 'mars', 'avr.', 'mai', 'juin', 'juil.', 'août', 'sept.', 'oct.', 'nov.', 'déc.'];\n\n  function roundedTopBarPath(x, y, w, h, r) {\n    var bottom = y + h;\n    if (h < r) r = Math.max(h, 0);\n    return 'M' + x + ',' + bottom +\n      ' L' + x + ',' + (y + r) +\n      ' Q' + x + ',' + y + ' ' + (x + r) + ',' + y +\n      ' L' + (x + w - r) + ',' + y +\n      ' Q' + (x + w) + ',' + y + ' ' + (x + w) + ',' + (y + r) +\n      ' L' + (x + w) + ',' + bottom + ' Z';\n  }\n\n  function renderHistory() {\n    var entries = loadEntries();\n    var now = new Date();\n    var months = [];\n    for (var i = 5; i >= 0; i--) {\n      var d = new Date(now.getFullYear(), now.getMonth() - i, 1);\n      months.push({\n        key: d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0'),\n        label: MONTH_ABBR[d.getMonth()],\n        total: 0\n      });\n    }\n    entries.forEach(function (e) {\n      var k = e.date ? e.date.slice(0, 7) : null;\n      var m = months.filter(function (mm) { return mm.key === k; })[0];\n      if (m) m.total += e.amount;\n    });\n\n    var container = document.getElementById('historyContainer');\n    var deltaEl = document.getElementById('historyDelta');\n    var hasAny = months.some(function (m) { return m.total > 0; });\n\n    if (!hasAny) {\n      container.innerHTML = '<div class=\"chart-empty\">Reviens le mois prochain : dès que deux mois auront des gains enregistrés, tu pourras comparer.</div>';\n      deltaEl.textContent = '';\n      return;\n    }\n\n    var W = 320, H = 140, padL = 6, padR = 6, padT = 18, padB = 24;\n    var innerW = W - padL - padR, innerH = H - padT - padB;\n    var maxV = Math.max.apply(null, months.map(function (m) { return m.total; })) * 1.25 || 1;\n    var n = months.length;\n    var slot = innerW / n;\n    var barW = Math.min(30, slot * 0.5);\n\n    var bars = months.map(function (m, i) {\n      var cx = padL + slot * i + slot / 2;\n      var barH = (m.total / maxV) * innerH;\n      var y = padT + innerH - barH;\n      var isCurrent = i === n - 1;\n      var fill = isCurrent ? 'var(--pay-eleve)' : 'var(--bar-muted)';\n      var valueColor = isCurrent ? 'var(--ink)' : 'var(--ink-faint)';\n      var valLabel = m.total > 0 ? m.total.toFixed(0) + '€' : '—';\n      return '' +\n        (barH > 0 ? '<path d=\"' + roundedTopBarPath(cx - barW / 2, y, barW, barH, 4) + '\" style=\"fill:' + fill + '\"/>' : '') +\n        '<text x=\"' + cx + '\" y=\"' + (y - 5) + '\" text-anchor=\"middle\" font-size=\"8.5\" font-weight=\"700\" font-family=\"IBM Plex Mono, monospace\" fill=\"' + valueColor + '\">' + valLabel + '</text>' +\n        '<text x=\"' + cx + '\" y=\"' + (padT + innerH + 15) + '\" text-anchor=\"middle\" font-size=\"8\" font-family=\"Manrope, sans-serif\" fill=\"var(--ink-faint)\">' + m.label + '</text>';\n    }).join('');\n\n    container.innerHTML = '<svg viewBox=\"0 0 ' + W + ' ' + H + '\" width=\"100%\" height=\"140\">' +\n      '<line x1=\"' + padL + '\" y1=\"' + (padT + innerH) + '\" x2=\"' + (W - padR) + '\" y2=\"' + (padT + innerH) + '\" stroke=\"var(--line)\" stroke-width=\"1\"/>' +\n      bars + '</svg>';\n\n    var current = months[n - 1].total;\n    var previous = months[n - 2].total;\n    if (previous === 0 && current === 0) {\n      deltaEl.textContent = '';\n    } else if (previous === 0) {\n      deltaEl.innerHTML = 'Premier mois avec des gains enregistrés — continue comme ça.';\n    } else {\n      var diff = current - previous;\n      var pct = Math.round((diff / previous) * 100);\n      var diffStr = (diff >= 0 ? '+' : '') + diff.toFixed(2).replace('.', ',') + ' €';\n      if (diff > 0) {\n        deltaEl.innerHTML = '▲ <strong style=\"color:var(--pay-eleve)\">' + diffStr + '</strong> vs le mois dernier (' + (pct >= 0 ? '+' : '') + pct + ' %)';\n      } else if (diff < 0) {\n        deltaEl.innerHTML = '▼ <strong style=\"color:var(--ink-faint)\">' + diffStr + '</strong> vs le mois dernier (' + pct + ' %)';\n      } else {\n        deltaEl.innerHTML = '→ <strong>Identique</strong> au mois dernier';\n      }\n    }\n  }\n\n  function renderTracker() {\n    var entries = loadEntries();\n    var monthEntries = entries.filter(function (e) { return isThisMonth(e.date); });\n    var monthEntriesSorted = monthEntries.slice().sort(function (a, b) {\n      return (a.date || '').localeCompare(b.date || '') || a.id - b.id;\n    });\n    var total = monthEntries.reduce(function (sum, e) { return sum + e.amount; }, 0);\n    var totalStr = total.toFixed(2).replace('.', ',') + ' €';\n\n    document.getElementById('trackerPillAmount').textContent = totalStr;\n    document.getElementById('drawerTotalAmount').textContent = totalStr;\n\n    document.getElementById('statSurveys').textContent = monthEntries.filter(function (e) { return SURVEY_NAMES.indexOf(e.source) !== -1; }).length;\n    document.getElementById('statTrials').textContent = monthEntries.filter(function (e) { return TRIAL_NAMES.indexOf(e.source) !== -1; }).length;\n\n    renderChart(monthEntriesSorted);\n    renderHistory();\n    renderGuarantee();\n    renderTier();\n    renderSurveys();\n    bindCardEvents();\n\n    var list = document.getElementById('drawerList');\n    if (!entries.length) {\n      list.innerHTML = '<div class=\"drawer-empty\">Aucune entrée pour l’instant — ajoute ton premier gain reçu pour commencer le suivi.</div>';\n      return;\n    }\n    var sorted = entries.slice().sort(function (a, b) { return (b.date || '').localeCompare(a.date || ''); });\n    list.innerHTML = sorted.map(function (e) {\n      return '' +\n        '<div class=\"entry-row\">' +\n          '<span>' +\n            '<span class=\"src\">' + e.source + '</span>' +\n            '<span class=\"date-note\">' + (e.date || '') + '</span>' +\n          '</span>' +\n          '<span>' +\n            '<span class=\"amt\">' + e.amount.toFixed(2).replace('.', ',') + ' €</span>' +\n            '<button class=\"del\" data-entry-id=\"' + e.id + '\">✕</button>' +\n          '</span>' +\n        '</div>';\n    }).join('');\n\n    list.querySelectorAll('.del').forEach(function (btn) {\n      btn.addEventListener('click', function () {\n        var id = btn.getAttribute('data-entry-id');\n        var remaining = loadEntries().filter(function (e) { return String(e.id) !== id; });\n        saveEntries(remaining);\n        renderTracker();\n      });\n    });\n  }\n\n  function initTracker() {\n    var select = document.getElementById('entrySource');\n    var options = surveys.map(function (s) { return s.name; }).concat(trials.map(function (t) { return t.name; }));\n    select.innerHTML = options.map(function (name) { return '<option value=\"' + name + '\">' + name + '</option>'; }).join('') + '<option value=\"Autre\">Autre</option>';\n\n    var dateInput = document.getElementById('entryDate');\n    dateInput.value = new Date().toISOString().slice(0, 10);\n\n    document.getElementById('trackerPillBtn').addEventListener('click', function () {\n      document.getElementById('drawerOverlay').classList.add('open');\n    });\n    document.getElementById('drawerClose').addEventListener('click', function () {\n      document.getElementById('drawerOverlay').classList.remove('open');\n    });\n    document.getElementById('drawerOverlay').addEventListener('click', function (ev) {\n      if (ev.target.id === 'drawerOverlay') ev.currentTarget.classList.remove('open');\n    });\n\n    document.getElementById('drawerForm').addEventListener('submit', function (ev) {\n      ev.preventDefault();\n      var amount = parseFloat(document.getElementById('entryAmount').value);\n      if (!amount || amount <= 0) return;\n      var entries = loadEntries();\n      entries.push({\n        id: Date.now(),\n        source: select.value,\n        amount: amount,\n        date: dateInput.value || new Date().toISOString().slice(0, 10)\n      });\n      saveEntries(entries);\n      document.getElementById('entryAmount').value = '';\n      renderTracker();\n    });\n\n    renderTracker();\n  }\n\n  document.addEventListener('DOMContentLoaded', function () {\n    loadState();\n    renderSurveys();\n    renderTrials();\n    renderOffres(dateSeed());\n    bindCardEvents();\n\n    document.getElementById('tabSondages').addEventListener('click', function () { switchTab('sondages'); });\n    document.getElementById('tabEssais').addEventListener('click', function () { switchTab('essais'); });\n    document.getElementById('tabOffres').addEventListener('click', function () { switchTab('offres'); });\n    document.getElementById('tabIntl').addEventListener('click', function () { switchTab('intl'); });\n    document.querySelectorAll('.tab-btn').forEach(function (b) {\n      b.addEventListener('click', function () { switchTab(b.getAttribute('data-tab')); });\n    });\n\n    document.getElementById('shuffleBtn').addEventListener('click', function () {\n      renderOffres(Math.random() * 100000);\n    });\n\n    initTracker();\n\n    document.querySelectorAll('#chipsSondages .chip').forEach(function (chip) {\n      chip.addEventListener('click', function () {\n        document.querySelectorAll('#chipsSondages .chip').forEach(function (c) { c.classList.remove('active'); });\n        chip.classList.add('active');\n        state.filterS = chip.getAttribute('data-filter');\n        renderSurveys();\n        bindCardEvents();\n      });\n    });\n\n    document.querySelectorAll('#chipsEssais .chip').forEach(function (chip) {\n      chip.addEventListener('click', function () {\n        document.querySelectorAll('#chipsEssais .chip').forEach(function (c) { c.classList.remove('active'); });\n        chip.classList.add('active');\n        state.filterE = chip.getAttribute('data-filter');\n        if (state.filterE !== 'tous') bumpUsage('cat_' + state.filterE);\n        renderTrials();\n        bindCardEvents();\n      });\n    });\n\n    document.getElementById('listEssais').addEventListener('click', function (ev) {\n      var link = ev.target.closest('.open-btn');\n      if (link) {\n        var card = link.closest('.card');\n        var cat = card ? card.getAttribute('data-cat') : null;\n        if (cat) bumpUsage('cat_' + cat);\n      }\n    });\n\n    getInstallDate();\n    renderGuarantee();\n    renderTier();\n    renderPrefList();\n    applyPersonalization(true);\n\n    document.getElementById('settingsBtn').addEventListener('click', function () {\n      document.getElementById('prefOverlay').classList.add('open');\n    });\n    document.getElementById('prefClose').addEventListener('click', function () {\n      document.getElementById('prefOverlay').classList.remove('open');\n    });\n    document.getElementById('prefOverlay').addEventListener('click', function (ev) {\n      if (ev.target.id === 'prefOverlay') ev.currentTarget.classList.remove('open');\n    });\n\n    document.getElementById('premiumClose').addEventListener('click', function () {\n      document.getElementById('premiumOverlay').classList.remove('open');\n    });\n    document.getElementById('premiumOverlay').addEventListener('click', function (ev) {\n      if (ev.target.id === 'premiumOverlay') ev.currentTarget.classList.remove('open');\n    });\n    document.getElementById('confirmPremiumBtn').addEventListener('click', function () {\n      setPremiumPaid();\n      document.getElementById('premiumOverlay').classList.remove('open');\n      renderTier();\n      renderPrefList();\n      applyPersonalization(true);\n      renderSurveys();\n      bindCardEvents();\n    });\n\n    document.getElementById('premiumPlusClose').addEventListener('click', function () {\n      document.getElementById('premiumPlusOverlay').classList.remove('open');\n    });\n    document.getElementById('premiumPlusOverlay').addEventListener('click', function (ev) {\n      if (ev.target.id === 'premiumPlusOverlay') ev.currentTarget.classList.remove('open');\n    });\n    document.getElementById('confirmPremiumPlusBtn').addEventListener('click', function () {\n      setPremiumPlusPaid();\n      document.getElementById('premiumPlusOverlay').classList.remove('open');\n      renderIntl();\n    });\n  });\n})();\n</script>\n\n</body></html>";
